const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Cambodia';
  const cambodiaGeom = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', countryName))
    .geometry();

  const date1_start = '2018-02-01';
  const date1_end = '2018-03-01'; // Exclusive end date

  const date2_start = '2017-08-01';
  const date2_end = '2017-09-01'; // Exclusive end date

  // 2. Data Acquisition
  const fireCollection = ee.ImageCollection('MODIS/061/MCD14ML');

  // Filter for February 2018
  const fires2018 = fireCollection
    .filterDate(date1_start, date1_end)
    .filterBounds(cambodiaGeom);

  // Filter for August 2017
  const fires2017 = fireCollection
    .filterDate(date2_start, date2_end)
    .filterBounds(cambodiaGeom);

  // 3. Calculation
  // We use .select(0) to turn the ImageCollection into a single image of detections over the period,
  // then count the number of non-null pixels. This is an efficient way to count detections.
  const reducer = ee.Reducer.count();
  const scale = 1000; // MODIS resolution for this product

  const count2018Promise = fires2018.select(0).count().reduceRegion({
    reducer: reducer,
    geometry: cambodiaGeom,
    scale: scale,
    maxPixels: 1e9
  }).get('count');

  const count2017Promise = fires2017.select(0).count().reduceRegion({
    reducer: reducer,
    geometry: cambodiaGeom,
    scale: scale,
    maxPixels: 1e9
  }).get('count');

  // Execute the computations
  const count2018 = await ee.Number(count2018Promise).getInfo();
  const count2017 = await ee.Number(count2017Promise).getInfo();

  // 4. Validation & Final Answer
  if (count2018 === null || count2017 === null) {
    console.log("Could not retrieve fire count for one or both periods.");
    console.log("A: C3");
    return;
  }

  console.log(`Cambodia fire detections (Feb 2018): ${count2018}`);
  console.log(`Cambodia fire detections (Aug 2017): ${count2017}`);

  if (count2018 > count2017) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e.message}`);
    console.error("D");
  }
}

initEE();
